cd /workspace/results/grpo_countdown && python3 -I - <<'EOF'
import json
steps={}
for l in open('metrics.jsonl'):
    r=json.loads(l); steps.setdefault(r['step'],{}).update(r.get('data',{}))
for s in sorted(steps):
    d=steps[s]
    keys=[k for k in d if 'reward' in k or 'acc' in k or 'score/mean' in k or 'entropy' in k or 'response_length/mean' in k or 'clip_ratio' in k or 'grad_norm' in k or 'pg_clipfrac' in k or 'kl_loss' in k or 'ppo_kl' in k]
    print(s, {k:round(d[k],5) if isinstance(d[k],float) else d[k] for k in keys})
EOF

